import React from 'react';
//import { Routes, Route } from 'react-router-dom';
import { Routes, Route, Navigate } from 'react-router-dom'; // CHANGED


import Home from './components/Home';
import Details from './components/Details';
import Summary from './components/QEInitiatives/Summary';
import ProjectROI from './components/ROI/ProjectROI';
import ProjectLeadROIEntry from './components/ROI/ProjectLeadROIEntry';

import SummaryTab from './components/ROI/tabs/SummaryTab';

import ProjectSavingsTab from './components/ROI/tabs/ProjectSavingsTab';      // unchanged file
import InitiativeSavingsTab from './components/ROI/tabs/InitiativeSavingsTab'; // unchanged file
import SOASavingsTab from './components/ROI/tabs/SOASavingsTab';               // unchanged file

import MonthlyBreakupTab from './components/ROI/tabs/MonthlyBreakupTab';


function App() {
  return (
    <Routes>
      <Route path="/" element={<Home />} />
      <Route path="/details/:value" element={<Details />} />
	  <Route path="/QEInitiatives/Summary" element={<Summary />} />
	  <Route path="/ROI/ProjectROI" element={<ProjectROI />} />
	  
	  
	      <Route path="/ROI/ProjectLeadROIEntry/:intakeNumber" element={<ProjectLeadROIEntry />}>
	          <Route index element={<Navigate to="summary" replace />} />
	          <Route path="summary" element={<SummaryTab />} />
	          <Route path="project-savings" element={<ProjectSavingsTab />} />
	          <Route path="initiative-savings" element={<InitiativeSavingsTab />} />
	          <Route path="soa-savings" element={<SOASavingsTab />} />
	          <Route path="monthly-breakup" element={<MonthlyBreakupTab />} />
	     </Route>
	  
    </Routes>
  );
}

export default App;
